from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class OperationStatus(SchemaObject):
    status = SchemaField(name="status")
    reason = SchemaField(name="reason")

    def __init__(self, status, reason):
        self.status = status
        self.reason = reason
        super(OperationStatus, self).__init__()
